    document.querySelectorAll('[data-copy-direct]').forEach(b=>b.onclick=()=>{const p=this.state.players.find(x=>x.id===b.dataset.copyDirect);if(p)this.copyDirectInvite(p)});
    document.querySelectorAll('[data-copy-invite]').forEach(b=>b.onclick=()=>{const p=this.state.players.find(x=>x.id===b.dataset.copyInvite);if(p)this.copyPlayerInviteLink(p)});
    document.querySelectorAll('[data-wa-invite]').forEach(b=>b.onclick=()=>{const p=this.state.players.find(x=>x.id===b.dataset.waInvite);if(p)this.copyPlayerWhatsapp(p)});
