  renderClaim(){
    clearTimeout(this.claimTimer);const pending=(this.state?.claims||[]).filter(c=>c.status==='pending');
    if(!pending.length){$('claimOverlay').classList.remove('show');this.claimShown='';$('claimWindowText').textContent='';$('claimList').innerHTML='';return}
    if(this.currentClaimOpen!==false)$('claimOverlay').classList.add('show');const key=pending.map(c=>c.id).join(',');if(key!==this.claimShown){this.claimShown=key;this.currentClaimOpen=true;$('claimOverlay').classList.add('show')}
    const first=pending.slice().sort((a,b)=>(a.receivedSequence||0)-(b.receivedSequence||0))[0],autoMs=Number(this.state?.claimAutoVerifyMs||10000),receivedAt=new Date(first.receivedAt||first.createdAt||Date.now()).getTime(),left=Math.max(0,receivedAt+autoMs-Date.now());
    const auditLeft=Math.max(0,Number(this.state.claimWindow?.expiresAtMs||0)-Date.now());
    $('claimWindowText').innerHTML=`${auditLeft>0?`Esperando otras alertas · ${(auditLeft/1000).toFixed(1)} s · `:''}<b>verificación automática en ${Math.ceil(left/1000)} s</b>`;
    $('claimList').innerHTML=pending.sort((a,b)=>(a.receivedSequence||0)-(b.receivedSequence||0)).map((c,i)=>`<article class="claimItem ${c.officialValid?'valid':'invalid'}"><b>${i+1}. ${esc(c.prizeLabel||c.type)} · ${esc(c.playerName)} · Cartón ${esc(c.cardNumber)}</b><div>#${esc(c.receivedSequence||'—')} ${i?`· +${Math.max(0,Number(c.deltaFromFirstMs)||0)} ms`:''}</div><div>${c.officialValid?'<strong>VALIDACIÓN CORRECTA</strong>':'<strong>INVÁLIDO</strong>: no cumple el premio'}</div><div class="actions" style="margin-top:7px"><button class="btn primary" data-confirm="${c.id}" ${!c.officialValid||auditLeft>0?'disabled':''}>VERIFICAR AHORA</button><button class="btn secondary" data-reject="${c.id}" ${auditLeft>0?'disabled':''}>RECHAZAR</button></div></article>`).join('');
    document.querySelectorAll('[data-confirm]').forEach(b=>b.onclick=()=>this.resolve(b.dataset.confirm,'confirmed'));document.querySelectorAll('[data-reject]').forEach(b=>b.onclick=()=>this.resolve(b.dataset.reject,'rejected'));this.claimTimer=setTimeout(()=>this.renderClaim(),250)
  }
  renderDrawer(){if(!this.state?.active)return;document.querySelectorAll('[data-drawer]').forEach(b=>b.classList.toggle('active',b.dataset.drawer===this.drawerTab));const d=this.state;if(this.drawerTab==='numbers'){const nums=[...d.game.drawn].sort((a,b)=>a-b);$('drawerContent').innerHTML=`<h3>NÚMEROS SALIDOS · ${nums.length}</h3><div class="numberGrid">${nums.map(n=>`<span>${n}</span>`).join('')}</div>`}else if(this.drawerTab==='winners'){const wins=(d.claims||[]).filter(c=>c.status==='confirmed');$('drawerContent').innerHTML=`<h3>GANADORES</h3>${wins.map(c=>`<div class="summaryBox"><b>${esc(c.prizeLabel||c.type)}</b><span>${esc(c.playerName)} · Cartón ${esc(c.cardNumber)}</span><span>${esc(c.receivedAtDisplay||c.resolvedAt||'')}</span></div>`).join('')||'<span class="muted">Todavía no hay premios confirmados.</span>'}`}else{$('drawerContent').innerHTML=`<h3>EVENTOS</h3>${(d.eventLog||[]).slice(-80).reverse().map(e=>`<div class="summaryBox"><b>${esc(e.type)}</b><span>${new Date(e.at).toLocaleTimeString('es-AR')}</span></div>`).join('')}`}}
