  async toggleJoin(){try{this.apply(await this.req('/api/admin/join-open',{method:'POST',body:JSON.stringify({open:!this.state.roomSettings.joinOpen})}))}catch(e){this.toast(e.message)}}
  async start(){
    const plan=this.state?.startPlan||{},summary=this.state?.registrationSummary||{};
    const requested=this.state.players.reduce((sum,p)=>sum+(p.cardIds?.length||0),0);
    if(this.state.roomSettings?.adminSimulation){if(!confirm(`Iniciar ahora la simulación con ${this.state.players.length} IA y ${requested} cartones?`))return;return this.startConfirmed(true)}
    const eligible=Number(plan.eligiblePlayers||0),auto=Number(plan.autoAssignPlayers||0),pendingPay=Number(plan.pendingPaymentPlayers||0),selected=Number(plan.selectedPlayers||0),cards=Number(summary.confirmedCards||0);
    if(this.state.roomSettings?.joinOpen)return this.toast('Primero cerrá las inscripciones. Cerrarlas no inicia el sorteo.');
    if(eligible<2)return this.toast('Se necesitan al menos 2 jugadores habilitados. No hace falta que estén conectados en este momento.');
    if(pendingPay>0)return this.toast(`Hay ${pendingPay} pago${pendingPay===1?'':'s'} pendiente${pendingPay===1?'':'s'}. Confirmalos o quitá esos jugadores antes de iniciar.`);
    const meta=`<b>${eligible} JUGADORES HABILITADOS · ${cards} CARTONES</b><span>${selected} ya eligieron · ${auto} recibirán automáticamente su cantidad autorizada.</span><span>Los jugadores registrados que todavía no abrieron su link podrán entrar más tarde con sus cartones ya asignados.</span><span>Al iniciar habrá un período de preparación/tutorial antes de la primera bolilla.</span>`;
    if(eligible>20){$('largeRoomStartMeta').innerHTML=meta;this.openModal('startCriterionModal');return}
    if(!confirm(`Iniciar sorteo con ${eligible} jugadores y ${cards} cartones?
${auto} recibirán cartones automáticamente.
Habrá unos segundos de preparación antes de la primera bolilla.`))return;await this.startConfirmed()
  }
